@startuml

class Library {
}

class User {
  + SecurityDeposit : float
  + ContactInfo : string[]
}

class BorrowableItem {
  + LibraryCode : string
  + Location : string
  + MaxReturnPeriod : string
}

class Book extends BorrowableItem {
  + Publisher : string
}

class MagazineIssue extends BorrowableItem {
  + PublicationDate : date
  + Publisher : string
}

class MusicCD extends BorrowableItem {
  + Publisher : string
  + Artist : string
}

class VHSFilm extends BorrowableItem {
  + Duration : int
  + Publisher : string
}

class DVDFilm extends BorrowableItem {
  + Duration : int
  + Publisher : string
}

class Author {
}

class Actor {
}

class Request {
}

Library "1" -- "*" User
Library "1" -- "*" BorrowableItem
User "0..1" -- "0..3" BorrowableItem : borrows
Book "*" -- "1..*" Author
VHSFilm "*" -- "1..*" Actor
DVDFilm "*" -- "1..*" Actor
Library "0..*" -- "0..*" Library : requests item from

@enduml

